"""Invoices for Priya's studio: rates, line totals and a rendered invoice.

House rules, kept by the tests in tests/ and audited by check.py:

* Money is rounded half up to two decimals. Not with round(), which rounds half
  to even: round(2.675, 2) is 2.67 where the accountant expects 2.68.
* Billable time rounds up to the next six-minute block, so 61 minutes bills as
  1.1 hours, not 1.0166.
* A line marked nonbillable is still shown on the invoice but adds nothing to
  any total.
* An unknown rate code raises UnknownRate, never KeyError.
* Codes in LOYALTY are discounted: long-standing clients get ten percent off.

A line is a dict: date, task, code, minutes, and optionally nonbillable.
parse_line(text) parses Priya's pasted rows, 'date code minutes task...',
into such a dict; anything else raises ValueError.
"""

from decimal import ROUND_HALF_UP, Decimal

RATES = {"dev": 92.25, "review": 68.25, "admin": 43.50}
LOYALTY = {"review"}
LOYALTY_DISCOUNT = 0.90


class UnknownRate(Exception):
    pass


def money(amount):
    """Round half up to two decimals."""
    return float(Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def billable_hours(minutes):
    """Minutes as hours, rounded up to the next six-minute block."""
    return -(-int(minutes) // 6) / 10


def rate_for(code):
    if code not in RATES:
        raise UnknownRate(code)
    rate = RATES[code]
    if code in LOYALTY:
        return money(rate * LOYALTY_DISCOUNT)
    return rate


def line_total(line):
    return money(billable_hours(line["minutes"]) * rate_for(line["code"]))


def invoice_total(lines):
    return money(sum(line_total(l) for l in lines if not l.get("nonbillable")))


def day_total(lines, date):
    """What we bill for one date: billable line totals for that date, rounded."""
    return money(
        sum(
            line_total(l)
            for l in lines
            if l["date"] == date and not l.get("nonbillable")
        )
    )


def summary(lines):
    """Hours per task name, every line included, billable or not."""
    totals = {}
    for line in lines:
        totals[line["task"]] = money(totals.get(line["task"], 0) + billable_hours(line["minutes"]))
    return totals


def estimate(minutes, code):
    """What a block of work would cost, before doing it."""
    return money(billable_hours(minutes) * rate_for(code))


def parse_line(text):
    """Turn one pasted row, 'date code minutes task ...', into a line dict."""
    if not isinstance(text, str):
        raise ValueError(f"expected a string, got {type(text).__name__}")
    parts = text.split(None, 3)
    if len(parts) != 4:
        raise ValueError(f"expected 'date code minutes task', got {text!r}")
    date, code, minutes_text, task = parts
    try:
        minutes = int(minutes_text)
    except ValueError:
        raise ValueError(f"minutes must be a whole number, got {minutes_text!r}") from None
    return {"date": date, "task": task, "code": code, "minutes": minutes}


def render_line(line):
    mark = " (nonbillable)" if line.get("nonbillable") else ""
    return f"{line['task']}\t{billable_hours(line['minutes']):.1f}h\t{line_total(line):.2f}{mark}"


def render_invoice(lines):
    """The whole invoice as one string: every rendered line, then a TOTAL row.

    Accepts line dicts or raw pasted rows as parse_line() reads them.
    """
    rows = [_as_dicts([line])[0] for line in lines]
    rendered = [render_line(line) for line in rows]
    rendered.append(f"TOTAL\t\t{invoice_total(rows):.2f}")
    return "\n".join(rendered)


def _as_dicts(lines):
    return [line if isinstance(line, dict) else parse_line(line) for line in lines]

